/**
 * Find the [start, end) ranges of the code spans in an inline run, reading
 * it left to right as the inline lexer does: a backslash escapes the next
 * character outside a code span, and a backtick run opens a code span only
 * if a run of the same length closes it.
 */
#codeSpanRanges(src: string): [number, number][] {
  const ranges: [number, number][] = [];
  if (!src.includes('`')) {
    return ranges;
  }

  let i = 0;
  while (i < src.length) {
    const char = src.charAt(i);
    if (char === '\\') {
      i += 2;
      continue;
    }
    if (char !== '`') {
      i++;
      continue;
    }

    let openEnd = i;
    while (src.charAt(openEnd) === '`') openEnd++;
    const length = openEnd - i;

    let j = openEnd;
    let close = -1;
    while ((j = src.indexOf('`', j)) !== -1) {
      let runEnd = j;
      while (src.charAt(runEnd) === '`') runEnd++;
      if (runEnd - j === length) {
        close = runEnd;
        break;
      }
      j = runEnd;
    }

    if (close === -1) {
      i = openEnd;
    } else {
      ranges.push([i, close]);
      i = close;
    }
  }

  return ranges;
}

